double baud = 9600;
int dataBits = 8, parityBits = 0, stopBits = 1;
int bitsPerChar = 1 + dataBits + parityBits + stopBits;
double bitTimeUs = 1_000_000 / baud;
double requestMs = 9 * bitsPerChar * 1000 / baud;
double responseMs = 10 * bitsPerChar * 1000 / baud;
Console.WriteLine($"bit={bitTimeUs:F6}us request={requestMs:F6}ms response={responseMs:F6}ms");
